(()=>{'use strict';
const form=document.getElementById('idx-filters');if(!form)return;
const fr=document.documentElement.lang.startsWith('fr'),tr=(a,b)=>fr?b:a,prefix=fr?'/fr':'',
status=document.getElementById('idx-status'),updated=document.getElementById('idx-updated'),grid=document.getElementById('idx-results'),pagination=document.getElementById('idx-pagination'),dialog=document.getElementById('idx-detail'),content=document.getElementById('idx-detail-content');
const disclaimer=tr('Listing information is deemed reliable but is not guaranteed accurate by PropTx.','Les renseignements sont jugés fiables, mais leur exactitude n’est pas garantie par PropTx.');
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=String(text);if(cls)n.className=cls;return n;};
const link=(text,href,cls)=>{const a=el('a',text,cls);a.href=href;return a;};
const money=v=>v===null||v===undefined?tr('Contact for price','Prix sur demande'):new Intl.NumberFormat(fr?'fr-CA':'en-CA',{style:'currency',currency:'CAD',maximumFractionDigits:0}).format(v);
const address=r=>r.UnparsedAddress||[r.UnitNumber?`${r.UnitNumber}–`:'',r.StreetNumber,r.StreetName,r.StreetSuffix,r.StreetDirSuffix].filter(Boolean).join(' ')||tr('Address available on request','Adresse sur demande');
const safeImage=url=>{try{return new URL(url).protocol==='https:';}catch{return false;}};
const photo=(url,alt,cls)=>{if(!safeImage(url))return el('div',tr('Photo unavailable','Photo non disponible'),'idx-no-photo');const img=el('img',undefined,cls);img.src=url;img.alt=alt;img.loading='lazy';img.decoding='async';img.addEventListener('error',()=>img.replaceWith(el('div',tr('Photo unavailable','Photo non disponible'),'idx-no-photo')),{once:true});return img;};
function facts(r){const bits=[];const beds=r.BedroomsTotal??r.BedroomsAboveGrade;if(beds!=null)bits.push(`${beds} ${tr('beds','chambres')}`);if(r.BathroomsTotalInteger!=null)bits.push(`${r.BathroomsTotalInteger} ${tr('baths','salles de bains')}`);if(r.ParkingTotal!=null)bits.push(`${r.ParkingTotal} ${tr('parking','stationnements')}`);return bits.join(' · ');}
function attribution(r){return el('p',tr('Listed by: ','Inscription : ')+[...new Set([r.ListOfficeName,r.CoListOfficeName].filter(Boolean))].join(' · '),'idx-attribution');}
let rows=[],controller=null,page=1,expires=0,expiryTimer=null,detailRequest=0;
function close(){dialog.close();content.replaceChildren();detailRequest++;const url=new URL(location.href);url.searchParams.delete('listing');history.replaceState(null,'',url.pathname+url.search+url.hash);}
document.getElementById('idx-close').addEventListener('click',close);dialog.addEventListener('cancel',e=>{e.preventDefault();close();});dialog.addEventListener('click',e=>{if(e.target===dialog)close();});
function detail(r){
 content.replaceChildren();const head=el('div',undefined,'idx-detail-head');head.append(el('p',r.TransactionType||'','eyebrow'),el('h2',address(r)));head.lastChild.id='idx-detail-title';head.append(el('p',money(r.ListPrice)+(r.ListPriceUnit&&r.ListPriceUnit!==r.TransactionType?' / '+r.ListPriceUnit:''),'idx-price'),el('p',[r.CityRegion,r.City,r.PostalCode].filter(Boolean).join(' · ')),el('p',facts(r)),attribution(r),el('p','MLS® '+(r.ListingId||r.ListingKey)));content.append(head);
 const gallery=el('div',undefined,'idx-gallery');(r.photos||[]).forEach((url,i)=>gallery.append(photo(url,`${address(r)} · ${tr('Photo','Photo')} ${i+1}`)));content.append(gallery);
 const body=el('div',undefined,'idx-detail-body');if(r.PropertySubType)body.append(el('p',r.PropertySubType));if(r.LivingAreaRange)body.append(el('p',tr('Living area: ','Superficie habitable : ')+r.LivingAreaRange));if(r.PublicRemarks){body.append(el('h3',tr('About this property','À propos de cette propriété')),el('p',r.PublicRemarks,'idx-remarks'));}body.append(el('p',disclaimer,'idx-detail-disclaimer'));content.append(body);
 const contact=el('aside',undefined,'idx-detail-contact');contact.append(el('h3',tr('Interested in a viewing?','Une visite vous intéresse?')),el('p','Ekaterina Ottchenach · HomeLife Frontier Realty Inc., Brokerage'),el('p',tr('Your representative for this inquiry. The listing brokerage is shown above.','Votre représentante pour cette demande. La maison de courtage inscriptrice est indiquée ci-dessus.')));
 contact.append(link(tr('Ask Ekaterina about this property','Parler de cette propriété à Ekaterina'),prefix+'/ask-realtor/?listing='+encodeURIComponent(r.ListingId||r.ListingKey),'button'),link('(647) 838-5569','tel:+16478385569','text-link'));content.append(contact);
 if(!dialog.open)dialog.showModal();dialog.scrollTop=0;const url=new URL(location.href);url.searchParams.set('listing',r.ListingKey);history.replaceState(null,'',url.pathname+url.search+url.hash);
}
async function openListing(id){const request=++detailRequest;status.textContent=tr('Checking availability…','Vérification de la disponibilité…');try{const response=await fetch('/api/listings.php?deal=all&id='+encodeURIComponent(id),{cache:'no-store',signal:AbortSignal.timeout(15000)});if(!response.ok)throw Error();const data=await response.json();if(request!==detailRequest)return;if(!data.listings.length){status.textContent=tr('This property is no longer available in the current feed.','Cette propriété n’est plus disponible dans le flux actuel.');return;}detail(data.listings[0]);status.textContent=tr('Property details opened.','Détails de la propriété ouverts.');}catch{status.textContent=tr('Could not verify this property. Please try again or contact Ekaterina.','Impossible de vérifier cette propriété. Réessayez ou contactez Ekaterina.');}}
function render(r){const card=el('article',undefined,'idx-card');const button=el('button',undefined,'idx-photo-button');button.type='button';button.setAttribute('aria-label',tr('View property: ','Voir la propriété : ')+address(r));button.append(photo(r.photos?.[0],address(r)));button.addEventListener('click',()=>openListing(r.ListingKey));card.append(button);const body=el('div',undefined,'idx-card-body');body.append(el('p',r.TransactionType||'','idx-transaction'),el('p',money(r.ListPrice)+(r.ListPriceUnit&&r.ListPriceUnit!==r.TransactionType?' / '+r.ListPriceUnit:''),'idx-price'),el('h3',address(r)),el('p',[r.CityRegion,r.City].filter(Boolean).join(' · ')),el('p',facts(r)),el('p',r.PropertySubType||''),attribution(r),el('p','MLS® '+(r.ListingId||r.ListingKey)));const more=el('button',tr('View details & photos','Voir les détails et photos'),'text-link');more.type='button';more.addEventListener('click',()=>openListing(r.ListingKey));body.append(more,el('p',disclaimer,'idx-card-disclaimer'));card.append(body);return card;}
function invalidate(){grid.replaceChildren();pagination.replaceChildren();rows=[];if(dialog.open)close();status.textContent=tr('Refreshing listing availability…','Actualisation des propriétés disponibles…');load(page);}
async function load(next=1){
 controller?.abort();controller=new AbortController();const active=controller;page=next;const params=new URLSearchParams(new FormData(form));params.set('page',page);grid.setAttribute('aria-busy','true');status.textContent=tr('Loading available properties…','Chargement des propriétés disponibles…');form.querySelector('[type=submit]').disabled=true;
 try{const response=await fetch('/api/listings.php?'+params,{cache:'no-store',signal:AbortSignal.any([active.signal,AbortSignal.timeout(15000)])});if(!response.ok)throw Error('unavailable');const data=await response.json();if(active!==controller)return;
 rows=data.listings;grid.replaceChildren(...rows.map(render));status.textContent=data.total?tr(`${data.total} matching properties · Page ${data.page} of ${Math.ceil(data.total/data.pageSize)}`,`${data.total} propriétés correspondantes · Page ${data.page} sur ${Math.ceil(data.total/data.pageSize)}`):tr('No properties match these filters. Try broadening your search or ask Ekaterina for help.','Aucune propriété ne correspond aux filtres. Élargissez la recherche ou contactez Ekaterina.');
 updated.textContent=tr('Last updated: ','Dernière mise à jour : ')+new Intl.DateTimeFormat(fr?'fr-CA':'en-CA',{dateStyle:'medium',timeStyle:'short',timeZone:'America/Toronto'}).format(new Date(data.updatedAt))+tr(' (Toronto time). Refresh scheduled every 15 minutes.',' (heure de Toronto). Actualisation prévue toutes les 15 minutes.');
 expires=new Date(data.updatedAt).getTime()+3600000;clearTimeout(expiryTimer);expiryTimer=setTimeout(invalidate,Math.max(1000,Math.min(900000,expires-Date.now())));
 const type=form.elements.type,selected=type.value;type.replaceChildren(new Option(tr('Any','Tous'),''),...data.types.map(x=>new Option(x,x)));type.value=selected;
 pagination.replaceChildren();for(const [label,n]of [[tr('Previous','Précédente'),page-1],[tr('Next','Suivante'),page+1]]){const b=el('button',label,'button');b.type='button';b.disabled=n<1||n>Math.ceil(data.total/data.pageSize);b.addEventListener('click',()=>{load(n);status.focus({preventScroll:true});document.getElementById('property-search').scrollIntoView({behavior:'smooth'});});pagination.append(b);}
 const url=new URL(location.href);for(const key of ['deal','min','max','beds','baths','type','sort','page'])url.searchParams.delete(key);params.forEach((v,k)=>{if(v&&!(k==='page'&&v==='1'))url.searchParams.set(k,v);});history.replaceState(null,'',url.pathname+url.search+url.hash);
 }catch(e){if(active!==controller)return;grid.replaceChildren();pagination.replaceChildren();updated.textContent='';if(dialog.open)close();status.textContent=tr('Listings are temporarily unavailable. Please try again or contact Ekaterina at (647) 838-5569.','Les annonces sont temporairement indisponibles. Réessayez ou contactez Ekaterina au (647) 838-5569.');}finally{if(active===controller){grid.removeAttribute('aria-busy');form.querySelector('[type=submit]').disabled=false;}}
}
if(!['nobleton.ca','localhost','127.0.0.1'].includes(location.hostname)){form.hidden=true;status.textContent=tr('Browse current listings on Nobleton.ca.','Consultez les annonces actuelles sur Nobleton.ca.');status.append(' ',link(tr('Open property search','Ouvrir la recherche'),'https://nobleton.ca'+prefix+'/homes-for-sale/','text-link'));return;}
const initial=new URLSearchParams(location.search);for(const key of ['deal','min','max','beds','baths','sort'])if(initial.has(key))form.elements[key].value=initial.get(key);if(initial.get('type'))form.elements.type.add(new Option(initial.get('type'),initial.get('type'),true,true));
form.addEventListener('submit',e=>{e.preventDefault();if(form.reportValidity())load(1);});form.addEventListener('reset',()=>setTimeout(()=>load(1),0));document.addEventListener('visibilitychange',()=>{if(!document.hidden&&Date.now()>=expires)invalidate();});
load(Math.max(1,Number(initial.get('page'))||1));if(initial.get('listing'))openListing(initial.get('listing'));
})();
